fn is_valid_hex_path(path: &String) -> bool {
    if path.is_empty() {
        return false;
    }
    for part in path.split(":") {
        if part.is_empty() {
            return false;
        }
        if !part.chars().all(|c| c.is_ascii_hexdigit()) {
            return false;
        }
    }
    true
}

